import { Component } from '@angular/core';
import { PctAvatarBase } from './avatar';

function mixinOrder<T extends new (...args: any[]) => PctAvatarBase>(B: T) {
  return class extends B {
    protected override order(): number {
      return 5;
    }
  };
}

@Component({
  selector: 'pct-plain',
  template: '',
})
export class PctPlain extends mixinOrder(PctAvatarBase) {}
